-- Notes joueurs (60-99), calculees par scripts/ratings.py. A executer apres 02_data.sql.
BEGIN;
ALTER TABLE stats_joueur_saison ADD COLUMN note smallint CHECK (note BETWEEN 60 AND 99);
ALTER TABLE stats_joueur_saison ADD COLUMN poste_note text CHECK (poste_note IN ('Goalkeeper','Defender','Midfielder','Forward'));
COMMENT ON COLUMN stats_joueur_saison.note IS 'Note 60-99 par joueur et saison : meilleure note parmi les postes occupes (poste_note), algorithme propre a chaque poste (voir scripts/ratings.py). Independante de note_moyenne (WhoScored).';
UPDATE stats_joueur_saison s SET note = v.note, poste_note = v.poste_note
